"""Post-evaluation aggregation: never passed to the reader."""
from collections import Counter
import hashlib, html, json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).resolve().parent

def load(path): return json.loads(path.read_text())
def digest(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def norm(s):
    import unicodedata
    return ' '.join(unicodedata.normalize('NFKC',s).casefold().split())
def dump(name, value): (OUT/name).write_text(json.dumps(value,indent=2)+'\n')

sets=[];rows=[];manifests=[]
for b in (10,11,12):
    base=ROOT/f'evidence/read300/batch-{b:03d}'
    summary=load(base/'rule-evaluation/summary.json')
    audit=load(base/'rule-evaluation/audit.json')
    assert all(audit[k] for k in ('recomputed_summary_matches','source_unchanged','frozen_files_unchanged','source_retention_all'))
    sets.append(dict(set=b,**summary))
    rows += [dict(set=b,**json.loads(line)) for line in (base/'rule-evaluation/scored.jsonl').read_text().splitlines()]
    manifests.append(load(base/'rule-evaluation/manifest.json'))
assert all(m['source_hashes']==manifests[0]['source_hashes'] and m['parser_hashes']==manifests[0]['parser_hashes'] for m in manifests)
texts={norm(r['text']) for r in rows}
old={norm(r['text']) for b in range(1,10) for r in load(ROOT/f'evidence/read300/batch-{b:03d}/inputs.json')}
assert len(texts)==900 and not texts & old
freeze=load(ROOT/'evidence/question-role-fix-2/reader-freeze.json')
assert all(digest(ROOT/p)==h for p,h in freeze.items())
failures=[r for r in rows if not r['correct_code_proposal']]
coverage=Counter(rule for r in rows if r['correct_code_proposal'] for rule in r['result']['code_proposal']['rules'])
summary=dict(kind='fresh lexical combinations within existing voice_tense construction; not full READ accuracy',
    cases=len(rows),unique_sentences=len(texts),correct=sum(r['correct_code_proposal'] for r in rows),
    incorrect=sum(r['code_routed'] and not r['correct_code_proposal'] for r in rows),
    unresolved=sum(not r['code_routed'] for r in rows),source_retained=sum(r['source_retained'] for r in rows),
    new_model_calls=0,correct_AI=None,correct_ASK=None,
    accuracy=sum(r['correct_code_proposal'] for r in rows)/len(rows),
    by_set=[{k:s[k] for k in ('set','cases','code_correct','code_incorrect','unresolved','correct_code_over_all')} for s in sets],
    correct_rule_coverage=dict(coverage),final_routes=dict(Counter(r['result']['route'] for r in rows)),
    read_seconds=sum(s['seconds'] for s in sets),context_flagged=sum(s['context_flagged'] for s in sets),
    audit=dict(all_three_pass=True,all_unique=True,disjoint_from_sets_1_to_9=True,same_source_and_parser=True,reader_freeze_unchanged=True),
    caveats=['Only existing voice_tense grammar and existing vocabulary with new bindings; no new workflow families.',
        'Literal role-slot scoring does not verify all semantics, including tense representation.',
        'No active library, archive, ledger or correct-ASK evaluation in these 900 cases.',
        'Final ASK is from missing calibration; do not count it as justified semantic ASK.',
        'Fresh rule coverage is not a causal ablation tick; paired replay ticks are reported separately.'])
dump('summary.json',summary);dump('failures.json',failures)
replay=load(ROOT/'evidence/question-role-fix-2/summary.json')
older=load(ROOT/'evidence/question-role-fix-2/older-600-replay/summary.json')
replay_rows=[json.loads(line) for line in (ROOT/'evidence/question-role-fix-2/cases.jsonl').read_text().splitlines()]
e=html.escape
body='<h1>READ: three fresh sets after question-role fixes</h1>'
body+=f'<p class="result">{summary["correct"]}/900 correct ({summary["accuracy"]:.2%}) · {summary["incorrect"]} wrong · {summary["unresolved"]} unresolved</p>'
body+='<p>Frozen version 6; 300 new sentences per set, generated by unchanged Serpent constructors with independent graph-derived gold. No generative AI calls. Parsing does not require knowing the answer to a question.</p>'
body+='<table><tr><th>Set</th><th>Correct</th><th>Wrong</th><th>Unresolved</th><th>Accuracy</th></tr>'
for s in sets: body+=f'<tr><td>{s["set"]}</td><td>{s["code_correct"]}/300</td><td>{s["code_incorrect"]}</td><td>{s["unresolved"]}</td><td>{s["correct_code_over_all"]:.2%}</td></tr>'
body+='</table><h2>What this establishes</h2><ul>'+''.join('<li>'+e(c)+'</li>' for c in summary['caveats'])+'</ul>'
body+='<p>Source retention is 900/900 by design. All final routes are ASK because calibration remains absent. No production acceptance claim follows from these proposal scores. Each set exceeds 97.5% within this limited test scope.</p>'
body+='<h2>Rules, ascending by observed replay benefit</h2><table><tr><th>Rule</th><th>New flips in saved 1,087</th><th>Correct fresh cases covered</th></tr>'
for rule,ticks in sorted(replay['ticks_by_new_rule'].items(),key=lambda kv:kv[1]):body+=f'<tr><td>{e(rule)}</td><td>{ticks}</td><td>{coverage[rule]}</td></tr>'
body+='</table><p>C018 recognizes the complete BE + patient + optional not + participle + by + agent question when the dependency parser attaches the participle as a noun modifier. C019 uses a declared double-object verb and adjacent ordered noun phrases to assign recipient then patient. Neither rule hardcodes sentences or names.</p>'
body+=f'<p>Saved 1,087-case replay: {replay["before_correct"]} → {replay["after_correct"]}, {replay["ticks"]} flips, {replay["regressions"]} regressions. Older 600-case replay: {older["before_correct"]} → {older["after_correct"]}, {older["ticks"]} flips, {older["regressions"]} regressions. These are reused development results; the older set still has 204 unresolved cases.</p>'
body+='<h2>The unresolved case</h2>'
for r in failures:body+='<details open><summary>'+e(r['text'])+'</summary><pre>'+e(json.dumps(dict(expected=r['expected'],proposal=r['result']['code_proposal']),indent=2))+'</pre></details>'
body+='<p>The parser labels “key” as amod under “moved”, and “moved” as attr under “Is”. C018 requires an explicit subject and acl attachment, so it abstains. This is a grammar coverage gap, not missing WORLD knowledge or semantic ambiguity. No post-test repair was applied.</p>'
body+='<h2>Grounding and ASK boundary</h2><p>Missing context, unresolved pronouns and ambiguous or stale knowledge prevent AI fallback. Model identity assignments require independent deterministic evidence; unsupported IDs trigger ASK. Grammar-only fallback remains possible. Nine focused policy tests pass. This does not implement a general history, participant or ordinal resolver; quoted reference words and complement “that” can conservatively block fallback. The trusted direct gate API still assumes its caller supplies authoritative bindings.</p>'
body+='<h2>How scores were checked</h2><p>All 900 inputs are unique and disjoint from sets 1–9. The frozen reader saw only source sentences; scoring loaded teacher gold after capture. Three audits recomputed scores and checked source, parser and reference hashes. The regression suite ran 238 tests: 237 passed, one optional dependency skip. Captures, failures, manifests and references are saved alongside this report.</p>'
body+='<h2>145 development flips</h2>'
for r in replay_rows:
    if r['tick']:body+='<details><summary>✓ '+e(r['text'])+'</summary><pre>'+e(json.dumps(r['result']['code_proposal'],indent=2))+'</pre></details>'
body+='<h2>All 900 fresh cases</h2>'
for r in rows:body+='<details><summary>'+('✓ ' if r['correct_code_proposal'] else 'Unresolved: ')+e(r['text'])+'</summary><pre>'+e(json.dumps(dict(set=r['set'],id=r['id'],expected=r['expected'],proposal=r['result']['code_proposal'],score=r['score']),indent=2))+'</pre></details>'
page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>READ fresh sets 10–12</title><style>body{max-width:1050px;margin:30px auto;padding:20px;background:#112033;color:#edf3ff;font:16px/1.6 system-ui}.result{font-size:24px;font-weight:bold;color:#95e9ba}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}td,th{padding:10px;border:1px solid #657e97}table{border-collapse:collapse}details{margin:8px 0;padding:8px;border:1px solid #657e97}summary{cursor:pointer}</style>'+body+'</html>'
(ROOT/'reports/read-sets-010-012.html').write_text(page)
print(json.dumps(summary,indent=2))
